# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _student(last: str, first: str) -> Student:
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_splits_into_rows(self):
        people = [_student("Halloway", "Juno"), _student("Dunmere", "Piet"), _student("Adair", "Sol")]
        self.assertEqual(
            seat_rows(people, 2),
            ["Row 1: Adair, Sol | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows([_student("Adair", "Sol")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
